from AlgorithmImports import *


class ExactStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.SetWarmUp(100, Resolution.Daily)

        self.spy_lot_shares = 0
        self.aapl_lot_shares = 0

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.last_processed_date = None
        self.pending_orders = {}

    def OnData(self, data):
        current_date = self.Time.date()

        if self.last_processed_date == current_date:
            return

        self.last_processed_date = current_date

        spy_bar = data.Bars[self.spy] if self.spy in data.Bars else None
        aapl_bar = data.Bars[self.aapl] if self.aapl in data.Bars else None
        ibm_bar = data.Bars[self.ibm] if self.ibm in data.Bars else None
        bac_bar = data.Bars[self.bac] if self.bac in data.Bars else None
        aig_bar = data.Bars[self.aig] if self.aig in data.Bars else None

        spy_close = None
        current_spy_sma = None
        spy_cross_above = False
        spy_cross_below = False

        if spy_bar is not None:
            spy_close = float(spy_bar.Close)

            if self.spy_sma.IsReady:
                current_spy_sma = float(self.spy_sma.Current.Value)

                if self.previous_spy_close is not None and self.previous_spy_sma is not None:
                    spy_cross_above = (
                        self.previous_spy_close <= self.previous_spy_sma
                        and spy_close > current_spy_sma
                    )

                    spy_cross_below = (
                        self.previous_spy_close >= self.previous_spy_sma
                        and spy_close < current_spy_sma
                    )

        aapl_close = None
        aapl_red_streak_today = self.aapl_red_streak
        aapl_rsi_value = None

        if aapl_bar is not None:
            aapl_close = float(aapl_bar.Close)

            if self.previous_aapl_close is None:
                aapl_red_streak_today = 0
            elif aapl_close < self.previous_aapl_close:
                aapl_red_streak_today += 1
            else:
                aapl_red_streak_today = 0

            if self.aapl_rsi.IsReady:
                aapl_rsi_value = float(self.aapl_rsi.Current.Value)

        all_bars_present = (
            spy_bar is not None
            and aapl_bar is not None
            and ibm_bar is not None
            and bac_bar is not None
            and aig_bar is not None
        )

        if all_bars_present and not self.IsWarmingUp:
            if (
                self.spy_lot_shares > 0
                and spy_cross_below
                and not self._has_pending_order(self.spy)
            ):
                self._submit_order(
                    self.spy,
                    -self.spy_lot_shares,
                    "STRATEGY_A_SELL"
                )

            if (
                self.aapl_lot_shares > 0
                and aapl_rsi_value is not None
                and aapl_rsi_value > 60
                and not self._has_pending_order(self.aapl)
            ):
                self._submit_order(
                    self.aapl,
                    -self.aapl_lot_shares,
                    "STRATEGY_B_SELL"
                )

            if (
                self.spy_lot_shares == 0
                and spy_cross_above
                and current_spy_sma is not None
                and not self._has_pending_order(self.spy)
            ):
                target_value = float(self.Portfolio.TotalPortfolioValue) * 0.40
                quantity = int(target_value / spy_close)

                if quantity > 0:
                    self._submit_order(
                        self.spy,
                        quantity,
                        "STRATEGY_A_BUY"
                    )

            if (
                self.aapl_lot_shares == 0
                and aapl_red_streak_today >= 3
                and self.Portfolio.Cash >= 20000
                and not self._has_pending_order(self.aapl)
            ):
                quantity = int(20000 / aapl_close)

                if quantity > 0:
                    self._submit_order(
                        self.aapl,
                        quantity,
                        "STRATEGY_B_BUY"
                    )

        if spy_bar is not None:
            self.previous_spy_close = spy_close
            self.previous_spy_sma = current_spy_sma

        if aapl_bar is not None:
            self.previous_aapl_close = aapl_close
            self.aapl_red_streak = aapl_red_streak_today

    def _has_pending_order(self, symbol):
        return any(
            order_info[0] == symbol
            for order_info in self.pending_orders.values()
        )

    def _submit_order(self, symbol, quantity, role):
        ticket = self.MarketOrder(symbol, quantity, False, role)

        if ticket is None:
            return

        terminal_statuses = (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

        if ticket.Status not in terminal_statuses:
            self.pending_orders[ticket.OrderId] = (symbol, role)

    def OnOrderEvent(self, order_event):
        order_id = order_event.OrderId
        order_info = self.pending_orders.get(order_id)

        if order_info is None:
            order = self.Transactions.GetOrderById(order_id)

            if order is None:
                return

            order_info = (order.Symbol, order.Tag)

        symbol, role = order_info

        if order_event.Status in (
            OrderStatus.PartiallyFilled,
            OrderStatus.Filled
        ):
            fill_quantity = int(order_event.FillQuantity)

            if role in ("STRATEGY_A_BUY", "STRATEGY_A_SELL"):
                self.spy_lot_shares = max(
                    0,
                    self.spy_lot_shares + fill_quantity
                )

            elif role in ("STRATEGY_B_BUY", "STRATEGY_B_SELL"):
                self.aapl_lot_shares = max(
                    0,
                    self.aapl_lot_shares + fill_quantity
                )

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            self.pending_orders.pop(order_id, None)

