from AlgorithmImports import *
from collections import deque
from math import floor


class StrategySystemAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_closes = deque(maxlen=101)

        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.rsi_period = 14
        self.aapl_change_count = 0
        self.aapl_gain_sum = 0.0
        self.aapl_loss_sum = 0.0
        self.aapl_average_gain = None
        self.aapl_average_loss = None
        self.aapl_rsi_value = None
        self.aapl_rsi_ready = False

        self.lots = {
            "A": 0,
            "B": 0
        }

        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data: Slice):
        self._update_market_state(data)

        if self.IsWarmingUp:
            return

        if not all(symbol in data.Bars for symbol in self.symbols):
            return

        spy_close = float(data.Bars[self.spy].Close)
        aapl_close = float(data.Bars[self.aapl].Close)

        spy_crosses_above = self._spy_crosses_above_sma()
        spy_crosses_below = self._spy_crosses_below_sma()

        aapl_sell_reason = (
            self.aapl_rsi_ready and self.aapl_rsi_value > 60.0
        )

        if self.lots["A"] > 0 and spy_crosses_below:
            self._liquidate_lot("A", self.spy)

        if self.lots["B"] > 0 and aapl_sell_reason:
            self._liquidate_lot("B", self.aapl)

        if self.lots["A"] == 0 and spy_crosses_above:
            target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
            quantity = floor(target_value / spy_close)

            if quantity > 0:
                self.MarketOrder(self.spy, quantity, tag="Strategy A buy")
                self.lots["A"] = quantity

        if (
            self.lots["B"] == 0
            and self.aapl_red_streak >= 3
            and float(self.Portfolio.Cash) >= 20000.0
        ):
            quantity = floor(20000.0 / aapl_close)

            if quantity > 0:
                self.MarketOrder(self.aapl, quantity, tag="Strategy B buy")
                self.lots["B"] = quantity

    def _update_market_state(self, data: Slice):
        bars = data.Bars

        if self.spy in bars:
            self.spy_closes.append(float(bars[self.spy].Close))

        if self.aapl in bars:
            close = float(bars[self.aapl].Close)

            if self.aapl_previous_close is not None:
                change = close - self.aapl_previous_close

                if change < 0:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

                self._update_aapl_rsi(change)

            self.aapl_previous_close = close

    def _update_aapl_rsi(self, change):
        gain = max(change, 0.0)
        loss = max(-change, 0.0)

        self.aapl_change_count += 1

        if self.aapl_change_count <= self.rsi_period:
            self.aapl_gain_sum += gain
            self.aapl_loss_sum += loss

            if self.aapl_change_count == self.rsi_period:
                self.aapl_average_gain = (
                    self.aapl_gain_sum / self.rsi_period
                )
                self.aapl_average_loss = (
                    self.aapl_loss_sum / self.rsi_period
                )
                self.aapl_rsi_ready = True
        else:
            self.aapl_average_gain = (
                (self.aapl_average_gain * (self.rsi_period - 1) + gain)
                / self.rsi_period
            )
            self.aapl_average_loss = (
                (self.aapl_average_loss * (self.rsi_period - 1) + loss)
                / self.rsi_period
            )

        if self.aapl_rsi_ready:
            if self.aapl_average_loss == 0:
                self.aapl_rsi_value = 100.0
            else:
                relative_strength = (
                    self.aapl_average_gain / self.aapl_average_loss
                )
                self.aapl_rsi_value = (
                    100.0 - 100.0 / (1.0 + relative_strength)
                )

    def _spy_sma_values(self):
        if len(self.spy_closes) < 101:
            return None

        values = list(self.spy_closes)

        yesterday_close = values[-2]
        today_close = values[-1]

        yesterday_sma = sum(values[-101:-1]) / 100.0
        today_sma = sum(values[-100:]) / 100.0

        return yesterday_close, yesterday_sma, today_close, today_sma

    def _spy_crosses_above_sma(self):
        values = self._spy_sma_values()

        if values is None:
            return False

        yesterday_close, yesterday_sma, today_close, today_sma = values

        return (
            yesterday_close <= yesterday_sma
            and today_close > today_sma
        )

    def _spy_crosses_below_sma(self):
        values = self._spy_sma_values()

        if values is None:
            return False

        yesterday_close, yesterday_sma, today_close, today_sma = values

        return (
            yesterday_close >= yesterday_sma
            and today_close < today_sma
        )

    def _liquidate_lot(self, strategy, symbol):
        shares = self.lots[strategy]

        if shares > 0:
            self.MarketOrder(
                symbol,
                -shares,
                tag=f"Strategy {strategy} sell"
            )
            self.lots[strategy] = 0
