        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity(
            "SPY", Resolution.Daily, fillDataForward=False
        ).Symbol
        self.aapl = self.AddEquity(
