            if bars.ContainsKey(symbol) and bars[symbol] is not None:
                available[symbol] = bars[symbol]

        spy_bar = available.get(self.spy)
        aapl_bar = available.get(self.aapl)

        if aapl_bar is None:
            self.aapl_red_streak = 0
        else:
            if aapl_bar.Close < aapl_bar.Open:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        all_bars_present = len(available) == len(self.symbols)

        if (
            all_bars_present
            and not self.IsWarmingUp
            and spy_bar is not None
            and self.spy_sma.IsReady
            and self.aapl_rsi.IsReady
        ):
            today_spy_close = float(spy_bar.Close)
            today_spy_sma = float(self.spy_sma.Current.Value)

            spy_crossed_above = (
                self.previous_spy_close is not None
                and self.previous_spy_sma is not None
                and self.previous_spy_close <= self.previous_spy_sma
                and today_spy_close > today_spy_sma
            )

            spy_crossed_below = (
                self.previous_spy_close is not None
                and self.previous_spy_sma is not None
                and self.previous_spy_close >= self.previous_spy_sma
                and today_spy_close < today_spy_sma
            )

            aapl_rsi_above_60 = float(self.aapl_rsi.Current.Value) > 60

            if self.lots["A"] > 0 and spy_crossed_below:
                self._sell_entire_lot("A", self.spy, "A_SELL")

            if self.lots["B"] > 0 and aapl_rsi_above_60:
                self._sell_entire_lot("B", self.aapl, "B_SELL")

            if self.lots["A"] == 0 and spy_crossed_above:
                quantity = int(
                    math.floor(
                        0.40
                        * float(self.Portfolio.TotalPortfolioValue)
                        / today_spy_close
                    )
                )
                if quantity > 0:
                    self._buy_lot("A", self.spy, quantity, "A_BUY")

            if self.lots["B"] == 0 and self.aapl_red_streak >= 3:
                if self.Portfolio.Cash >= 20_000:
                    quantity = int(math.floor(20_000 / float(aapl_bar.Close)))
                    if quantity > 0:
                        self._buy_lot("B", self.aapl, quantity, "B_BUY")

        if spy_bar is not None:
            self.previous_spy_close = float(spy_bar.Close)
            if self.spy_sma.IsReady:
                self.previous_spy_sma = float(self.spy_sma.Current.Value)
            else:
                self.previous_spy_sma = None

    def _buy_lot(self, slot, symbol, quantity, tag):
        self.MarketOnCloseOrder(symbol, quantity, tag)
        self.lots[slot] = quantity

    def _sell_entire_lot(self, slot, symbol, tag):
        quantity = self.lots[slot]
        if quantity > 0:
            self.MarketOnCloseOrder(symbol, -quantity, tag)
            self.lots[slot] = 0
